#!/usr/bin/env python3
"""Build the Stylist AI journal from reviewed JSON articles; no external dependencies."""
from pathlib import Path
from html import escape
from datetime import date
import json, re, math, xml.etree.ElementTree as ET
ROOT = Path(__file__).resolve().parents[1]
BASE = '/stylist_ai/blog'
ORIGIN = 'https://bestme.mobi'
APP = 'https://apps.apple.com/app/id6739435502'
ASSETS = '/stylist_ai/landing/v2/assets'
ARTICLES = sorted([json.loads(f.read_text()) for f in (ROOT/'_stylist_ai/content').glob('*.json')], key=lambda a:a['datePublished'], reverse=True)
LATEST = max(a['dateModified'] for a in ARTICLES)
def e(s): return escape(str(s),quote=True)
def display(d): return date.fromisoformat(d).strftime('%B %d, %Y').replace(' 0',' ')
def url(a): return BASE+'/'+a['slug']+'/'
def save(path,text):
    p=ROOT/path.lstrip('/');p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text)
def minutes(a): return max(3,math.ceil(len(re.sub('<[^>]*>',' ',' '.join(s['html'] for s in a['sections'])).split())/210))
def badge(slug,place):
    return f'<a class="store" href="{APP}?utm_source=bestme&amp;utm_medium=website&amp;utm_campaign=stylist_journal&amp;utm_content={e(slug)}_{place}" data-app-cta="{place}" aria-label="Download Stylist AI on the App Store"><img src="{ASSETS}/app-store.svg" width="150" height="50" alt="Download on the App Store"></a>'
def palette():
    colors=['#A9A7C2','#AABBC1','#BEA0AD','#7E8897','#B49A7E','#AEAD8F','#C69C84','#8B7869']
    return '<div class="swatches" aria-label="Illustrative soft color comparison">'+''.join(f'<span style="--swatch:{c}"></span>' for c in colors)+'</div>'
def shell(title,desc,path,body,slug='home',schemas=None,article=False):
    canonical=ORIGIN+path
    schema=[{'@context':'https://schema.org','@type':'Organization','@id':ORIGIN+BASE+'/#publisher','name':'Stylist AI','url':ORIGIN+'/stylist_ai/','logo':ORIGIN+ASSETS+'/icon.png'}]+(schemas or [])
    graph=''.join('<script type="application/ld+json">'+json.dumps(s,ensure_ascii=False).replace('</','<\\/')+'</script>' for s in schema)
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="{canonical}"><meta name="robots" content="index,follow,max-image-preview:large"><meta name="theme-color" content="#fcf8f3"><meta name="referrer" content="strict-origin-when-cross-origin"><meta property="og:type" content="{'article' if article else 'website'}"><meta property="og:site_name" content="Stylist AI Journal"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{ORIGIN}{ASSETS}/social-coral.jpg"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="{ASSETS}/icon.png"><link rel="stylesheet" href="{BASE}/assets/site.css"><script defer src="{BASE}/assets/analytics.js"></script><script defer src="{BASE}/assets/site.js"></script>{graph}</head>
<body data-page="{e(slug)}"><a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="wrap nav"><a class="brand" href="{BASE}/"><img src="{ASSETS}/icon.png" width="38" height="38" alt=""><span>stylist <b>AI</b><small>THE COLOR JOURNAL</small></span></a><nav aria-label="Main navigation"><a href="{BASE}/#articles">Journal</a><a class="about-link" href="{BASE}/about/">Our approach</a><a class="app-nav" href="/stylist_ai/">Meet the app ↗</a></nav></div></header>{body}
<footer class="wrap footer"><div><a class="brand" href="{BASE}/">stylist <b>AI</b></a><small>Published by Aleksandr Korenev, the developer of Stylist AI.<br>Styling guidance is personal. Results and preferences vary.</small></div><nav aria-label="Footer"><a href="{BASE}/about/">About this journal</a><a href="{BASE}/privacy/">Website privacy</a><button data-privacy-choices hidden>Privacy choices</button><a href="/stylist-ai-privacy-policy.html">App privacy</a><a href="/stylist-ai-terms-of-use.html">App terms</a><a href="mailto:contact@bestme.mobi">Contact</a></nav></footer>
<section class="consent-panel" data-consent-panel aria-labelledby="consent-heading" hidden><div><h2 id="consent-heading">Help us improve the journal</h2><p>Allow optional Google Analytics to measure visits and App Store clicks? <a href="{BASE}/privacy/">Privacy notice</a>.</p></div><div class="consent-actions"><button type="button" data-consent-choice="denied">Decline</button><button class="primary" type="button" data-consent-choice="granted">Allow analytics</button></div></section></body></html>'''
def card(a):
    return f'<article class="guide-card"><a class="card-art" href="{url(a)}" tabindex="-1" aria-hidden="true">{palette()}</a><p class="eyebrow">{e(a["category"])} · {minutes(a)} min read</p><h3><a href="{url(a)}">{e(a["title"])}</a></h3><p>{e(a["excerpt"])}</p><a class="text-link" href="{url(a)}">Read the guide <span aria-hidden="true">↗</span></a></article>'
def home():
    newest=ARTICLES[0]
    body=f'''<main id="main"><section class="wrap hero"><div><p class="eyebrow">THE STYLIST AI JOURNAL</p><h1>A little color.<br>A lot more <em>you.</em></h1><p class="dek">Explore your colors, make sense of your palette, and get more from the clothes you love.</p><a class="button" href="{url(newest)}">Read our latest guide <span aria-hidden="true">↗</span></a><div class="hero-foot"><span>Color, without the rulebook.</span><span>01 / THE JOURNAL</span></div></div><div class="hero-image"><img src="{ASSETS}/color-combos-ai.webp" width="960" height="960" alt="Illustrated outfit color combinations in cobalt, white, pink and charcoal" fetchpriority="high"><span class="image-label">A PALETTE IS A STARTING POINT.</span></div></section><section class="intro-band"><div class="wrap"><p>Less second-guessing.<br><strong>More wearing what you love.</strong></p>{palette()}<span>Illustrative colors.<br>Your favorites are personal.</span></div></section><section id="articles" class="wrap library"><div class="section-head"><h2>Latest articles</h2></div><div class="cards">{''.join(card(a) for a in ARTICLES)}</div></section><section class="wrap app-block"><img src="{ASSETS}/icon.png" width="72" height="72" alt="Stylist AI app icon"><div><p class="eyebrow">YOUR COLORS, CLOSE AT HAND</p><h2>From a palette to an outfit.</h2><p>Explore color analysis, color combinations and a shopping color check in Stylist AI for iPhone.</p>{badge('home','home_end')}<small>Free download with in-app purchases.</small></div></section></main>'''
    schema=[{'@context':'https://schema.org','@type':'CollectionPage','name':'Stylist AI Journal','url':ORIGIN+BASE+'/','mainEntity':{'@type':'ItemList','itemListElement':[{'@type':'ListItem','position':i+1,'name':a['title'],'url':ORIGIN+url(a)} for i,a in enumerate(ARTICLES)]}}]
    save(BASE+'/index.html',shell('Color Analysis, Personal Palettes & Style Guides | Stylist AI','Explore helpful guides to seasonal color analysis, personal palettes and outfit colors. Discover styling ideas from Stylist AI that you can try today.',BASE+'/',body,schemas=schema))
def article(a):
    sections=''.join(f'<section aria-labelledby="{e(s["id"])}"><h2 id="{e(s["id"])}">{e(s["title"])}</h2>{s["html"]}</section>' for s in a['sections'])
    toc=''.join(f'<a href="#{e(s["id"])}">{e(s["title"])}</a>' for s in a['sections'])
    faqs=''.join(f'<details><summary>{e(f["question"])}</summary><p>{e(f["answer"])}</p></details>' for f in a.get('faqs',[]))
    sources=''.join(f'<li><a href="{e(s["url"])}">{e(s["title"])}</a></li>' for s in a['sources'])
    body=f'''<div class="reading-progress" aria-hidden="true"></div><main id="main" class="wrap"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="{BASE}/">Journal</a><span>/</span><span>{e(a['category'])}</span></nav><header class="article-header"><p class="eyebrow">{e(a['category'])}</p><h1>{e(a['title'])}</h1><p class="dek">{e(a['excerpt'])}</p><p class="byline">By <a href="{BASE}/about/">Stylist AI</a> <span>·</span> <time datetime="{a['datePublished']}">{display(a['datePublished'])}</time> <span>·</span> {minutes(a)} min read</p>{palette()}</header><div class="article-layout"><article class="article-body"><aside class="quick-answer"><p class="eyebrow">THE SHORT ANSWER</p><p>{e(a['quickAnswer'])}</p></aside>{sections}<section><h2>Common questions</h2>{faqs}</section><aside class="article-cta"><p class="eyebrow">MEET STYLIST AI</p><h2>{e(a['ctaTitle'])}</h2><p>{e(a['ctaText'])}</p>{badge(a['slug'],'article_end')}<small>For iPhone · In-app purchases · Results vary.</small></aside><section id="sources"><h2>Sources &amp; further reading</h2><p>Sources checked {display(a['sourcesChecked'])}. The comparison worksheet is our practical suggestion; seasonal categories are a styling framework. Sources have not endorsed this article or our app.</p><ul class="sources">{sources}</ul></section><p class="editorial-note">Published by the developer of Stylist AI. <a href="{BASE}/about/">Our editorial approach</a> · <a href="mailto:contact@bestme.mobi?subject=Journal%20correction">Suggest a correction</a></p><a class="text-link" href="{BASE}/">← Back to the journal</a></article><aside class="toc" aria-label="On this page"><p class="eyebrow">IN THIS GUIDE</p><a href="#main">The short answer</a>{toc}<a href="#sources">Sources</a></aside></div></main>'''
    schema=[{'@context':'https://schema.org','@type':'Article','headline':a['title'],'description':a['description'],'image':[ORIGIN+ASSETS+'/social-coral.jpg'],'datePublished':a['datePublished']+'T00:00:00+04:00','dateModified':a['dateModified']+'T00:00:00+04:00','author':{'@type':'Organization','name':'Stylist AI','url':ORIGIN+BASE+'/about/'},'publisher':{'@id':ORIGIN+BASE+'/#publisher'},'mainEntityOfPage':ORIGIN+url(a),'inLanguage':'en','citation':[s['url'] for s in a['sources']]},{'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Journal','item':ORIGIN+BASE+'/'},{'@type':'ListItem','position':2,'name':a['title'],'item':ORIGIN+url(a)}]}]
    save(url(a)+'index.html',shell(a['seoTitle'],a['description'],url(a),body,a['slug'],schema,True))
def info():
    about='''<p>This journal is published by Aleksandr Korenev, the developer of Stylist AI for iPhone. Explore color analysis, personal palettes and everyday styling through original guides and practical ideas.</p><h2>How we write</h2><p>We distinguish styling frameworks from measurable photography facts, link to relevant sources, and label our own practical suggestions. Guides may be prepared with AI assistance and are checked against the cited sources and verified product information. We do not claim professional color-consultant credentials or independent expert review.</p><h2>Our relationship with Stylist AI</h2><p>We make the app and benefit from subscriptions. Articles include clearly identified app links, alongside steps you can try without a purchase. Photos and camera conditions affect results; palettes and scores do not prove attractiveness or require you to follow a rule.</p><h2>Illustrations</h2><p>The outfit artwork is an illustration created for Stylist AI. Color strips are illustrative examples, not a calibrated reference or a personal analysis.</p><h2>Corrections</h2><p>Send the article URL and your correction to <a href="mailto:contact@bestme.mobi">contact@bestme.mobi</a>. Publication dates reflect publication; modification dates change when the content materially changes.</p>'''
    privacy='''<p>This notice applies to the Stylist AI journal at bestme.mobi/stylist_ai/blog. The app has a separate <a href="/stylist-ai-privacy-policy.html">privacy policy</a>.</p><h2>Optional analytics</h2><p>We load Google Analytics only if you allow it. It measures pages viewed, general traffic sources, App Store clicks and approximate article scroll progress. A click is not an installation, and scrolling does not prove someone read an article.</p><p>Google receives page paths and titles, browser and device information, and ordinary connection information. We remove query strings and fragments from page addresses; three validated campaign labels may be sent separately. External referrers are reduced to their origin. We do not collect photos or search text on this journal.</p><p>Your browser remembers your choice for up to 180 days. Analytics cookies use the sj prefix, are scoped to the journal and expire within 180 days. Advertising personalization and Google Signals are disabled. You can withdraw consent using Privacy choices; this stops future tracking and removes the journal’s Analytics cookies, but does not erase information Google already processed.</p><p data-consent-status role="status">Analytics is off until you allow it.</p><button data-privacy-choices hidden>Change privacy choices</button><p>See <a href="https://policies.google.com/privacy">Google’s privacy policy</a> and <a href="https://policies.google.com/technologies/partner-sites">how Google uses partner-site information</a>.</p><h2>Hosting and external links</h2><p>GitHub Pages hosts the journal and receives ordinary connection information; see <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub’s privacy statement</a>. The App Store and other linked sites have their own privacy rules. App Store links include non-personal campaign labels describing the article and button.</p><h2>Contact</h2><p>For privacy questions, contact <a href="mailto:contact@bestme.mobi">contact@bestme.mobi</a>. This website does not provide a user account or ask you to upload photographs.</p>'''
    for slug,title,desc,content in [('about','About the Stylist AI Journal','Learn who publishes the Stylist AI journal, how we use sources, and how our editorial guides relate to the Stylist AI app.',about),('privacy','Website Privacy | Stylist AI Journal','Understand optional analytics, cookies, App Store click measurement and your privacy choices when reading the Stylist AI color and style journal.',privacy)]:
        save(BASE+'/'+slug+'/index.html',shell(title,desc,BASE+'/'+slug+'/',f'<main id="main" class="wrap prose"><p class="eyebrow">THE STYLIST AI JOURNAL</p><h1>{title.split(" | ")[0]}</h1>{content}</main>',slug))
def sitemap():
    ns='http://www.sitemaps.org/schemas/sitemap/0.9';ET.register_namespace('',ns)
    root=ET.Element('{'+ns+'}urlset')
    items=[(BASE+'/',LATEST),(BASE+'/about/','2026-10-26'),(BASE+'/privacy/','2026-10-26')]+[(url(a),a['dateModified']) for a in ARTICLES]
    for path,modified in items:
        node=ET.SubElement(root,'{'+ns+'}url');ET.SubElement(node,'{'+ns+'}loc').text=ORIGIN+path;ET.SubElement(node,'{'+ns+'}lastmod').text=modified
    save(BASE+'/sitemap.xml',ET.tostring(root,encoding='unicode',xml_declaration=True))
    top=ROOT/'sitemap.xml';index=ET.parse(top).getroot()
    assert index.tag=='{'+ns+'}sitemapindex'
    loc=ORIGIN+BASE+'/sitemap.xml'
    node=next((x for x in index if x.findtext('{'+ns+'}loc')==loc),None)
    if node is None:
        node=ET.SubElement(index,'{'+ns+'}sitemap');ET.SubElement(node,'{'+ns+'}loc').text=loc
    last=node.find('{'+ns+'}lastmod')
    if last is None:last=ET.SubElement(node,'{'+ns+'}lastmod')
    last.text=LATEST;top.write_text(ET.tostring(index,encoding='unicode',xml_declaration=True))
if __name__=='__main__':
    assert len({a['slug'] for a in ARTICLES})==len(ARTICLES),'Duplicate slugs'
    home()
    for a in ARTICLES:article(a)
    info();sitemap();print(f'Built Stylist AI journal with {len(ARTICLES)} article(s).')
